new='metabolism.kit.diff.compose.json'
count=0
for r in roots:
  for p in r.rglob('*'):
    if not p.is_file():
      continue
    if p.suffix.lower() not in {'.ts','.tsx','.js','.jsx','.py','.go','.rs','.cs','.json','.md'}:
      continue
    try:s=p.read_text(encoding='utf-8')
    except:continue
    if old in s:
      p.write_text(s.replace(old,new),encoding='utf-8')
      count+=1
print('changed_files',count)
